const crypto = require('crypto');

const WATCHDOG_SECRET = '02194db639f32b2e643946d783fae76f74c1b49049efcbcb233c415b812e3f130c4db368b186f5fc2ce354e9e0f07ba7';
const REQUIRE_SIGNATURE = true;

const ALERTABLE_EVENTS = new Set([
  'user_register',
  'user_role_changed',
  'user_role_added',
  'user_meta_capabilities_added',
  'user_meta_capabilities_changed',
  'watched_user_meta_added',
  'watched_user_meta_changed',
  'watched_user_meta_deleted',
  'plugin_activated',
  'plugin_deactivated',
  'rest_sensitive_route',
  'admin_sensitive_action',
  'wp_login'
]);

const OPTION_EVENTS = new Set([
  'watched_option_changed',
  'watched_option_added',
  'watched_option_deleted'
]);

const HIGH_SIGNAL_OPTIONS = new Set([
  'active_plugins',
  'siteurl',
  'home',
  'admin_email',
  'users_can_register',
  'default_role',
  'rewrite_rules',
  'recently_activated'
]);

function getHeader(headers, name) {
  const target = String(name).toLowerCase();
  for (const pair of Object.entries(headers || {})) {
    const key = pair[0];
    const value = pair[1];
    if (String(key).toLowerCase() === target) {
      return Array.isArray(value) ? String(value[0] || '') : String(value || '');
    }
  }
  return '';
}

function getRawBody(input) {
  if (typeof input.rawBody === 'string') return input.rawBody;
  if (typeof input.raw_body === 'string') return input.raw_body;
  if (typeof input.bodyRaw === 'string') return input.bodyRaw;
  if (typeof input.body === 'string') return input.body;
  if (input.body && typeof input.body.rawBody === 'string') return input.body.rawBody;
  return JSON.stringify(input.body || {});
}

function parseEvent(input, rawBody) {
  if (input.body && typeof input.body === 'object' && !Array.isArray(input.body)) return input.body;
  if (typeof input.body === 'string' && input.body.trim() !== '') return JSON.parse(input.body);
  if (typeof rawBody === 'string' && rawBody.trim() !== '') return JSON.parse(rawBody);
  return input;
}

function safeTimingEqual(left, right) {
  const leftBuffer = Buffer.from(String(left));
  const rightBuffer = Buffer.from(String(right));
  return leftBuffer.length === rightBuffer.length && crypto.timingSafeEqual(leftBuffer, rightBuffer);
}

function isHighSignalOption(option) {
  const name = String(option || '');
  return HIGH_SIGNAL_OPTIONS.has(name)
    || name.indexOf('webhook') !== -1
    || name.indexOf('wpwhpro_') === 0
    || name.match(/(^|_)user_roles$/);
}

const input = items[0] && items[0].json ? items[0].json : {};
const headers = input.headers || {};
const signature = getHeader(headers, 'x-local-watchdog-signature');
const rawBody = getRawBody(input);
const rawBodyAvailable = typeof input.rawBody === 'string'
  || typeof input.raw_body === 'string'
  || typeof input.bodyRaw === 'string'
  || typeof input.body === 'string';

if (REQUIRE_SIGNATURE) {
  if (!WATCHDOG_SECRET || WATCHDOG_SECRET.indexOf('CHANGE_ME') === 0) {
    throw new Error('Local Watchdog secret is not configured in the n8n Verify + Normalize node.');
  }
  if (!signature) throw new Error('Missing X-Local-Watchdog-Signature header.');

  const expected = 'sha256=' + crypto.createHmac('sha256', WATCHDOG_SECRET).update(rawBody).digest('hex');
  if (!safeTimingEqual(signature, expected)) throw new Error('Invalid Local Watchdog signature.');
}

const event = parseEvent(input, rawBody);
const severity = String(event.severity || 'info').toLowerCase();
const eventType = String(event.event_type || 'unknown');
const option = event.data && event.data.option ? String(event.data.option) : '';
const restMethod = String((event.data && event.data.method) || '').toUpperCase();
const restRoute = String((event.data && event.data.route) || '').replace(/\/$/, '');

if (eventType === 'watched_option_changed' && option === 'cron') return [];

if (eventType === 'rest_sensitive_route' && restMethod === 'GET' && restRoute === '/wp/v2/users') return [];

const optionShouldAlert = OPTION_EVENTS.has(eventType) && isHighSignalOption(option);
const shouldAlert = ALERTABLE_EVENTS.has(eventType)
  || optionShouldAlert
  || (severity === 'critical' && !OPTION_EVENTS.has(eventType));

if (!shouldAlert) return [];

return [{
  json: Object.assign({}, event, {
    severity: severity,
    event_type: eventType,
    received_at: new Date().toISOString(),
    n8n_watchdog: {
      signature_required: REQUIRE_SIGNATURE,
      signature_valid: REQUIRE_SIGNATURE ? true : null,
      raw_body_available: rawBodyAvailable,
      workflow: 'BB Local Watchdog Alert'
    }
  })
}];

const event = items[0] && items[0].json ? items[0].json : {};

function escapeHtml(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function asJson(value) {
  if (value === undefined || value === null) return '';
  return escapeHtml(JSON.stringify(value, null, 2));
}

function row(label, value) {
  return '<tr><th style="text-align:left;padding:6px 10px;border-bottom:1px solid #ddd;background:#f7f7f7;width:190px;vertical-align:top;">'
    + escapeHtml(label)
    + '</th><td style="padding:6px 10px;border-bottom:1px solid #ddd;vertical-align:top;">'
    + (value || '')
    + '</td></tr>';
}

function severityColor(severity) {
  if (severity === 'critical') return '#b42318';
  if (severity === 'warning') return '#b54708';
  if (severity === 'notice') return '#175cd3';
  return '#344054';
}

const site = event.site || {};
const request = event.request || {};
const actor = event.actor || {};
const data = event.data || {};
const snapshot = event.snapshot || {};
const admins = Array.isArray(snapshot.admins) ? snapshot.admins : [];
const backtrace = Array.isArray(event.backtrace) ? event.backtrace : [];
const severity = String(event.severity || 'info').toLowerCase();
const eventType = String(event.event_type || 'unknown');
const siteHost = site.home_url || site.site_url || 'unknown-site';
const targetUser = data.user && (data.user.user_login || data.user.user_id) ? (data.user.user_login || data.user.user_id) : (data.user_login || '');

const adminsHtml = admins.length
  ? '<ul>' + admins.map(function(admin) {
      return '<li>#' + escapeHtml(admin.user_id) + ' ' + escapeHtml(admin.user_login)
        + (admin.user_email ? ' &lt;' + escapeHtml(admin.user_email) + '&gt;' : '')
        + (admin.user_registered ? ' (registered ' + escapeHtml(admin.user_registered) + ')' : '')
        + '</li>';
    }).join('') + '</ul>'
  : '<em>Keine Admin-Snapshot-Daten im Event.</em>';

const backtraceHtml = backtrace.length
  ? '<ol>' + backtrace.slice(0, 12).map(function(frame) {
      return '<li><code>' + escapeHtml([frame.class, frame.type, frame.function].filter(Boolean).join(''))
        + '</code><br><small>' + escapeHtml(frame.file || '')
        + (frame.line ? ':' + escapeHtml(frame.line) : '')
        + '</small></li>';
    }).join('') + '</ol>'
  : '<em>Kein Backtrace im Event.</em>';

const subject = ['[BB Watchdog]', severity.toUpperCase(), eventType, targetUser ? 'target=' + targetUser : ''].filter(Boolean).join(' - ');
const preStyle = 'white-space:pre-wrap;background:#f6f8fa;padding:12px;border:1px solid #d0d7de;border-radius:6px;overflow:auto;';

const html = [
  '<div style="font-family:Arial,Helvetica,sans-serif;color:#1d2939;line-height:1.45;">',
  '<h2 style="margin:0 0 8px;color:' + severityColor(severity) + ';">BB Local Watchdog Alert</h2>',
  '<p style="margin:0 0 16px;"><strong>Severity:</strong> <span style="color:' + severityColor(severity) + ';font-weight:bold;">' + escapeHtml(severity.toUpperCase()) + '</span> &nbsp; <strong>Event:</strong> <code>' + escapeHtml(eventType) + '</code></p>',
  '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;max-width:980px;border:1px solid #ddd;margin-bottom:18px;">',
  row('Event ID', escapeHtml(event.event_id || '')),
  row('Event time UTC', escapeHtml(event.timestamp_utc || '')),
  row('Received by n8n', escapeHtml(event.received_at || '')),
  row('Site', escapeHtml(siteHost)),
  row('Request URI', '<code>' + escapeHtml(request.uri || '') + '</code>'),
  row('Method', escapeHtml(request.method || '')),
  row('IP', escapeHtml(request.ip || request.remote_addr || '')),
  row('User-Agent', escapeHtml(request.user_agent || '')),
  row('Context', escapeHtml(['admin=' + request.is_admin, 'rest=' + request.is_rest, 'ajax=' + request.is_ajax, 'cron=' + request.is_cron, 'wp_cli=' + request.is_wp_cli].join(' | '))),
  row('Actor', actor.user_id ? '#' + escapeHtml(actor.user_id) + ' ' + escapeHtml(actor.user_login || '') + (actor.user_email ? ' &lt;' + escapeHtml(actor.user_email) + '&gt;' : '') + (actor.roles ? ' roles=' + escapeHtml((actor.roles || []).join(',')) : '') : 'anonymous / no current WP user'),
  row('Target', escapeHtml(targetUser || '')),
  row('Admin count in snapshot', escapeHtml(admins.length)),
  '</table>',
  '<h3>Event Data</h3>',
  '<pre style="' + preStyle + '">' + asJson(data) + '</pre>',
  '<h3>Admin Snapshot</h3>',
  adminsHtml,
  '<h3>Snapshot Raw</h3>',
  '<pre style="' + preStyle + '">' + asJson(snapshot) + '</pre>',
  '<h3>Backtrace</h3>',
  backtraceHtml,
  '<p style="color:#667085;font-size:12px;margin-top:24px;">Hinweis: Dieses Mail kommt vom n8n Workflow "BB Local Watchdog Alert". Das MU-Plugin beobachtet nur und nimmt keine automatischen Änderungen am Shop vor.</p>',
  '</div>'
].join('');

return [{ json: { subject: subject, html: html, event_type: eventType, severity: severity, event: event } }];
